30	export default async function Page(props: {
31	  params: Promise<PageParams>;
32	  searchParams: Promise<Record<string, string | string[] | undefined>>;
33	}) {
34	  // Next.js 16: params and searchParams are Promises and MUST be awaited.
35	  const { orgSlug } = await props.params;
36	  const search = await props.searchParams;
37	
38	  const { org, actor } = await loadTenantContext(orgSlug);
39	
40	  const advanced = isEnabled("advanced_search", buildFlagContext(actor, org));
41	  const query = typeof search.q === "string" ? search.q : "";
42	
43	  if (query.length === 0) {
44	    return (
45	      <div className="space-y-8">
46	        <SearchHeader orgSlug={orgSlug} query={query} advanced={advanced} />
47	        <EmptyState
48	          title="Search this organization"
49	          description="Type at least one character to look through issues, and — on the higher plans — comments and projects too."
50	        />
51	      </div>
52	    );
53	  }
