/**
 * Shared core of the `advanced_search` query language (ADR 0007). Both the
 * search dialog (for its hint line) and the search service (for query
 * execution) extract tokens with this function, so what the dialog says it
 * understood is what actually gets searched.
 *
 * This only extracts tokens; it does not decide defaults for missing kinds or
 * a missing project — callers differ on what "no token present" should mean.
 */

export type SearchSubjectKind = "issue" | "comment" | "project";

const KINDS: readonly SearchSubjectKind[] = ["issue", "comment", "project"];

export interface ExtractedSearchTokens {
  /** The free-text remainder, with every recognised token removed. */
  readonly text: string;
  /** Kinds named by `kind:`/`in:` tokens; empty when none were present. */
  readonly kinds: readonly SearchSubjectKind[];
  /** The value of a `project:` token, or null when none was present. */
  readonly projectId: string | null;
  /** Tokens that looked like `field:value` syntax but named nothing known. */
  readonly unknownTokens: readonly string[];
}

/**
 * @param raw      what the user typed
 * @param advanced whether the `advanced_search` flag is on for this org; when
 *                 false the whole string is free text — a colon is just a
 *                 character, never a field token.
 */
export function extractSearchTokens(
  raw: string,
  advanced: boolean,
): ExtractedSearchTokens {
  if (!advanced) {
    return { text: raw.trim(), kinds: [], projectId: null, unknownTokens: [] };
  }

  const terms: string[] = [];
  const kinds: SearchSubjectKind[] = [];
  const unknown: string[] = [];
  let projectId: string | null = null;

  for (const token of raw.split(/\s+/).filter((part) => part.length > 0)) {
    const separator = token.indexOf(":");
    if (separator <= 0) {
      terms.push(token);
      continue;
    }

    const field = token.slice(0, separator).toLowerCase();
    const value = token.slice(separator + 1);
    if (value.length === 0) {
      unknown.push(token);
      continue;
    }

    if (field === "kind" || field === "in") {
      const kind = value.toLowerCase().replace(/s$/, "") as SearchSubjectKind;
      if (KINDS.includes(kind)) kinds.push(kind);
      else unknown.push(token);
    } else if (field === "project") {
      projectId = value;
    } else {
      unknown.push(token);
    }
  }

  return {
    text: terms.join(" "),
    kinds,
    projectId,
    unknownTokens: unknown,
  };
}

